# Surah Al-Isra (chapter 17) — part 10: ayat 91-100 (IDs 2120-2129)
SURAH = 17

ENTRIES = {
2120: (
"یا تمہارے لیے کھجوروں اور انگوروں کا ایک باغ ہو اور تو اس کے درمیان سے چشمے پھوڑ دے",
"""۱۔ منکرین کا مطالبہ: جادوئی مظاہر — باغ اور چشمے؛ اپنی بات منوانے کے لیے۔
۲۔ ’’أَوْ تَكُونَ لَكَ جَنَّۃٌ مِّن نَّخِيلٍ وَعِنَبٍ فَتُفَجِّرَ الْأَنْهَارَ خِلَالَهَا تَفْجِيرًا‘‘ — یا تمہارے لیے کھجوروں اور انگوروں کا ایک باغ ہو اور تو اس کے درمیان سے چشمے پھوڑ دے — یعنی یا تمہارے لیے کھجوروں اور انگوروں کا باغ ہو اور تو ان کے درمیان سے چشمے نکال دے۔
۳۔ عملی سبق: ایمان نشانیوں کی شرط سے نہیں ملتا؛ دل ایمان لائے تو قرآن کافی ہے۔"""
),
2121: (
"یا آسمان ہمارے اوپر ٹکڑوں میں گر جائے جیسا کہ تو کہتا ہے — یا تو اللہ اور فرشتوں کو ہمارے سامنے لے آئے",
"""۱۔ منکرین کے اور زیادہ مطالبے: آسمان کا گرنا؛ اللہ اور فرشتے ہمارے سامنے آئیں۔
۲۔ ’’أَوْ تُسْقِطَ السَّمَاءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِيَ بِاللَّهِ وَالْمَلَائِكَۃِ قَبِيلًا‘‘ — یا آسمان ہمارے اوپر ٹکڑوں میں گر جائے جیسا کہ تو کہتا ہے — یا تو اللہ اور فرشتوں کو ہمارے سامنے لے آئے — یعنی یا آسمان ہمارے اوپر ٹکڑوں میں گر جائے جیسا کہ تو کہتا ہے یا اللہ اور فرشتوں کو ہمارے سامنے لے آئے۔
۳۔ عملی سبق: منکرین کے مطالبات بے بنیاد تھے؛ اللہ کی نشانیاں عقل کے لیے کافی ہیں۔"""
),
2122: (
"یا تمہاری چاندی کا کوئی محل ہو — یا تم آسمان پر چڑھ جاؤ — اور ہم آپ کے آسمان پر چڑھ جانے پر ایمان نہیں لائیں گے جب تک آپ ہمارے اوپر ایک کتاب نہ نازل کر دیں جسے ہم پڑھیں — کہیے میرا رب پاک ہے — کیا میں انسان رسول ہی تو ہوں",
"""۱۔ منکرین کے اور فحش مطالبات؛ نبیؐ نے فرمایا میرا رب پاک ہے؛ میں انسانِ رسول ہوں۔
۲۔ ’’أَوْ يَكُونَ لَكَ بَيْتٌ مِّن زُخْرُفٍ أَوْ تَرْقَىٰ فِي السَّمَاءِ وَلَن نُّؤْمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيْنَا كِتَابًا نَّقْرَؤُهُ قُلْ سُبْحَانَ رَبِّي هَلْ كُنتُ إِلَّا بَشَرًا رَّسُولًا‘‘ — یا تمہاری چاندی کا کوئی محل ہو — یا تم آسمان پر چڑھ جاؤ — اور ہم آپ کے آسمان پر چڑھ جانے پر ایمان نہیں لائیں گے جب تک آپ ہمارے اوپر ایک کتاب نہ نازل کر دیں جسے ہم پڑھیں — کہیے میرا رب پاک ہے — کیا میں انسان رسول ہی تو ہوں — یعنی یا تمہارا چاندی کا گھر ہو یا تم آسمان پر چڑھ جاؤ — اور ہم تمہارے چڑھنے پر ایمان نہیں لائیں گے جب تک ہم پر ایک کتاب نازل نہ کر دیں جو ہم پڑھیں — کہہ دو میرا رب پاک ہے — کیا میں ایک انسان رسول ہی تو ہوں۔
۳۔ عملی سبق: انبیاؑ انسان ہی ہیں؛ معجزے اللہ کے اختیار میں ہیں؛ زعمِ باطل سے بچو۔"""
),
2123: (
"اور لوگوں کو ہدایت آ جانے کے بعد ایمان سے کیا چیز مانع ہوئی سوائے اس کے کہ وہ کہتے رہے کہ کیا اللہ نے انسان کو رسول بنا کر بھیجا؟",
"""۱۔ مشرکین کا اعتراض: انسان رسول کیوں؟ بی جا تعجب؛ اللہ نے انسانوں میں سے رسول بھیجا۔
۲۔ ’’وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَىٰ إِلَّا أَن قَالُوا أَبَعَثَ اللَّهُ بَشَرًا رَّسُولًا‘‘ — اور لوگوں کو ہدایت آ جانے کے بعد ایمان سے کیا چیز مانع ہوئی سوائے اس کے کہ وہ کہتے رہے کہ کیا اللہ نے انسان کو رسول بنا کر بھیجا؟ — یعنی ہدایت آ جانے کے بعد ایمان نہ لائے مگر صرف اس لیے کہ وہ کہتے رہے کہ کیا اللہ نے انسان کو رسول بنایا؟
۳۔ عملی سبق: انبیاؑ انسان ہی ہوتے ہیں؛ تعجب تمہارا معیار نہیں ہونا چاہیے۔"""
),
2124: (
"کہیے اگر زمین میں فرشتے مطمئن چلتے پھرتے ہوتے تو ہم ان پر آسمان سے فرشتہ رسول بنا کر بھیج دیتے",
"""۱۔ رسول بھیجنے کا اللہ کا قانون: ایسے ہی جیسے زمین کے لوگ فرشتے ہوتے۔
۲۔ ’’قُل لَّوْ كَانَ فِي الْأَرْضِ مَلَائِكَۃٌ يَمْشُونَ مُطْمَئِنِّينَ لَنَزَّلْنَا عَلَيْهِم مِّنَ السَّمَاءِ مَلَكًا رَّسُولًا‘‘ — کہیے اگر زمین میں فرشتے مطمئن چلتے پھرتے ہوتے تو ہم ان پر آسمان سے فرشتہ رسول بنا کر بھیج دیتے — یعنی کہہ دو اگر زمین میں فرشتے مطمئن چلتے پھرتے تو ہم ان پر آسمان سے فرشتہ رسول نازل کر دیتے۔
۳۔ عملی سبق: رسول تمہارے ہی جیسے انسان ہیں؛ اسی لیے وہ تمہارے لیے سب سے زیادہ مناسب رہنما ہیں۔"""
),
2125: (
"کہیے اللہ کافی ہے میرے اور تمہارے درمیان گواہی دینے والا — بے شک وہ اپنے بندوں سے خوب خبر رکھنے والا دیکھنے والا ہے",
"""۱۔ اللہ گواہ ہے کہ آپؐ اللہ کے سچے رسول ہیں؛ مشرکین کے جھٹلانے کا جواب۔
۲۔ ’’قُلْ كَفَىٰ بِاللَّهِ شَهِيدًا بَيْنِي وَبَيْنَكُمْ إِنَّهُ كَانَ بِعِبَادِهِ خَبِيرًا بَصِيرًا‘‘ — کہیے اللہ کافی ہے میرے اور تمہارے درمیان گواہی دینے والا — بے شک وہ اپنے بندوں سے خوب خبر رکھنے والا دیکھنے والا ہے — یعنی کہہ دو اللہ ہی میرے اور تمہارے درمیان کافی گواہ ہے — بے شک وہ اپنے بندوں کا پورا جاننے والا دیکھنے والا ہے۔
۳۔ عملی سبق: اللہ گواہ ہے؛ حق کی دعوت پر ڈٹے رہو؛ اس کا سہارا لو۔"""
),
2126: (
"اور جسے اللہ ہدایت دے وہ ہدایت یافتہ ہے — اور جسے وہ گمراہ کرے تو آپ ان کے لیے اس کے سوا کوئی کارساز نہیں پائیں گے — اور ہم انہیں قیامت کے دن ان کے چہروں پر گھسیٹیں گے اندھے ہو کر گونگے ہو کر بہرے ہو کر — ان کا ٹھکانا جہنم ہے — جب بھی وہ بجھے گا ہم اسے بھڑکائیں گے",
"""۱۔ اللہ کی ہدایت اور گمراہی — اللہ کا فیصلہ؛ منکر کا انجام چہروں پر گھسیٹ کر جہنم؛ جہنم کبھی بجھتی نہیں۔
۲۔ ’’وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ لَهُمْ أَوْلِيَاءَ مِن دُونِهِ وَنَحْشُرُهُمْ يَوْمَ الْقِيَامَۃِ عَلَىٰ وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَّأْوَاهُمْ جَهَنَّمُ كُلَّمَا خَبَتْ زِدْنَاهُمْ سَعِيرًا‘‘ — اور جسے اللہ ہدایت دے وہ ہدایت یافتہ ہے — اور جسے وہ گمراہ کرے تو آپ ان کے لیے اس کے سوا کوئی کارساز نہیں پائیں گے — اور ہم انہیں قیامت کے دن ان کے چہروں پر گھسیٹیں گے اندھے ہو کر گونگے ہو کر بہرے ہو کر — ان کا ٹھکانا جہنم ہے — جب بھی وہ بجھے گا ہم اسے بھڑکائیں گے — یعنی جسے اللہ ہدایت دے وہ ہدایت یافتہ ہے اور جسے گمراہ کرے تو آپ اس کے سوا کوئی کارساز نہیں پائیں گے — اور ہم انہیں قیامت میں ان کے چہروں پر گھسیٹیں گے اندھے گونگے بہرے ہو کر — ان کا ٹھکانا جہنم ہے — جب بھی وہ بجھے گا ہم اسے مزید بھڑکائیں گے۔
۳۔ عملی سبق: اللہ کی ہدایت سے جڑے رہو؛ منکرین کے لیے جہنم تیار ہے۔"""
),
2127: (
"یہ ان کا بدلہ ہے اس لیے کہ انہوں نے ہماری آیات کا انکار کیا اور کہا تھا کہ کیا جب ہم ہڈیاں اور ریزہ ریزہ مٹی ہو جائیں گے تو ہم دوبارہ نئی خلقت میں اٹھائے جائیں گے؟",
"""۱۔ منکرین کا عذاب — آیات کے انکار کا نتیجہ؛ بعث بعد الموت کا انکار ان کی بدعت ہے۔
۲۔ ’’ذَٰلِكَ جَزَاؤُهُم بِأَنَّهُمْ كَفَرُوا بِآيَاتِنَا وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا‘‘ — یہ ان کا بدلہ ہے اس لیے کہ انہوں نے ہماری آیات کا انکار کیا اور کہا تھا کہ کیا جب ہم ہڈیاں اور ریزہ ریزہ مٹی ہو جائیں گے تو ہم دوبارہ نئی خلقت میں اٹھائے جائیں گے؟ — یعنی یہ ان کا بدلہ ہے اس لیے کہ انہوں نے ہماری آیات کا انکار کیا اور کہا کہ جب ہم ہڈیاں مٹی بن جائیں گے تو کیا ہم نئی خلقت میں اٹھائے جائیں گے۔
۳۔ عملی سبق: اللہ کی آیات کا انکار عذاب کا باعث ہے؛ بعث بعد الموت پر ایمان لاؤ۔"""
),
2128: (
"کیا انہوں نے نہیں دیکھا کہ اللہ جو آسمانوں اور زمین کا خالق ہے اس کے پاس ان کی مثل دوبارہ تخلیق کی قدرت ہے — اور اس نے ان کے لیے ایک مقررہ وقت مقرر کیا ہے جس میں کوئی شک نہیں — مگر ظالم انکار پر ہی اڑے رہے",
"""۱۔ اللہ نے آسمان و زمین بنائے؛ مردوں کو زندہ کرنا اس کے لیے آسان ہے؛ ظالم انکار کرتے رہے۔
۲۔ ’’أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَىٰ أَن يَخْلُقَ مِثْلَهُمْ وَجَعَلَ لَهُمْ أَجَلًا لَّا رَيْبَ فِيهِ فَأَبَى الظَّالِمُونَ إِلَّا كُفُورًا‘‘ — کیا انہوں نے نہیں دیکھا کہ اللہ جو آسمانوں اور زمین کا خالق ہے اس کے پاس ان کی مثل دوبارہ تخلیق کی قدرت ہے — اور اس نے ان کے لیے ایک مقررہ وقت مقرر کیا ہے جس میں کوئی شک نہیں — مگر ظالم انکار پر ہی اڑے رہے — یعنی کیا انہوں نے نہیں دیکھا کہ اللہ جس نے آسمان و زمین بنائے ان جیسوں کی تخلیق پر بھی قادر ہے — اور اس نے ان کے لیے ایک مقررہ وقت مقرر کیا ہے جس میں کوئی شک نہیں — مگر ظالم انکار پر ہی اڑے رہے۔
۳۔ عملی سبق: اللہ کی قدرت کا انکار نہ کرو؛ قیامت کا وقت مقررہ ہے۔"""
),
2129: (
"کہیے اگر تم میرے رب کی رحمت کے خزانوں کے مالک بن جاؤ تو بھی تم اسراف کے خوف سے خرچ کرنے کی ہمت نہ کر سکتے — اور انسان تنگ دل ہوتا ہے",
"""۱۔ انسان بخيل ہے؛ اللہ کی رحمت کے خزانے بے پناہ ہیں؛ انسان خود بخيل ہے۔
۲۔ ’’قُل لَّوْ أَنتُمْ تَمْلِكُونَ خَزَائِنَ رَحْمَۃِ رَبِّي إِذًا لَّأَمْسَكْتُمْ خَشْيَۃَ الْإِنفَاقِ وَكَانَ الْإِنسَانُ قَتُورًا‘‘ — کہیے اگر تم میرے رب کی رحمت کے خزانوں کے مالک بن جاؤ تو بھی تم اسراف کے خوف سے خرچ کرنے کی ہمت نہ کر سکتے — اور انسان تنگ دل ہوتا ہے — یعنی کہہ دو اگر تم میرے رب کی رحمت کے خزانوں کے مالک بن جاؤ تو بھی تم خرچ کے خوف سے بچنے کے لیے بخل کرو گے — اور انسان بہت بخيل ہوتا ہے۔
۳۔ عملی سبق: بخل سے بچو؛ اللہ کا خزانہ لامحدود ہے؛ خرچ کرو اور شکر کرو۔"""
),
}
